def on_a_pressed():
    global netforce
    netforce = Rightforce - Leftforce
    Box.ax = netforce / mass
    Box.say_text("Netforce:" + ("" + str(netforce)))
    Box.say_text("a=" + ("" + str(netforce)) + "/" + ("" + str(mass)) + "=" + ("" + str(netforce / mass)))
controller.A.on_event(ControllerButtonEvent.PRESSED, on_a_pressed)

def on_left_pressed():
    global Leftforce
    Leftforce += 5
    Box.say_text("Leftforce:" + ("" + str(Leftforce)), 10000, False)
controller.left.on_event(ControllerButtonEvent.PRESSED, on_left_pressed)

def on_right_pressed():
    global Rightforce
    Rightforce += 5
    Box.say_text("Rightforce:" + ("" + str(Rightforce)), 10000, False)
controller.right.on_event(ControllerButtonEvent.PRESSED, on_right_pressed)

