def on_forever():
    if abs(Box.vx) <= 20 and Box.overlaps_with(Target):
        game.game_over(True)
    elif Box.overlaps_with(Target) and abs(Box.vx) > 20:
        game.game_over(False)
    else:
        pass
    velocity.set_text("Speed: " + ("" + str(Math.round(Box.vx))) + "px/s")
    velocity.set_position(72, 42)
    net.set_text("Netforce: " + str(netforce) + "")
    net.set_position(69, 52)
forever(on_forever)
